use xiom.io;
fn digit_sum(n: Int) -> Int {
  let mut sum = 0;
  let mut num = n;
  while num > 0 {
    sum += num % 10;
    num = num / 10;
  };
  sum
}

fn digital_root(n: Int) -> Int {
  let mut result = n;
  while result >= 10 {
    result = digit_sum(result);
  };
  result
}

fn main() -> Int {
  io.println(digit_sum(12345).to_str());
  io.println(digital_root(12345).to_str());
  return 0;
}
